import React from 'react';
import { Container, Button } from 'react-bootstrap';

const Hero = () => {
  return (
    <section className="text-center bg-light py-5">
      <Container>
        <h1 className="display-4">The Future of Banking</h1>
        <p className="lead">Experience seamless finance management with FI Money.</p>
        <Button variant="primary" href="#features">Get Started</Button>
      </Container>
    </section>
  );
};

export default Hero;
